  "stuSess.penaltyChoiceRefundDesc": "Ak chcete vrátiť platbu (€{amount}), kontaktujte info@tutlio.lt. Pri platbe kartou sa môže vrátenie spustiť automaticky cez Stripe.",
  "stuSess.creditAvailable": "Dostupný kredit",
