  "stuSess.creditAppliedSuccess": "Kredit vo výške €{amount} bol pripísaný k vášmu zostatku a automaticky sa použije na ďalšiu hodinu.",
  "stuSess.refundContactNote": "Ak chcete vrátiť platbu, kontaktujte <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Máte otázky alebo problémy? Kontaktujte <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Vrátenie vašej platby bolo spustené cez Stripe.</p><p class=\"text-emerald-800 mt-1\">Platby sa na kartu zvyčajne vrátia približne do <strong>5–10 pracovných dní</strong> (lehota závisí od banky). Ak peniaze nedostanete v obvyklej lehote, napíšte na <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Zdá sa, že táto hodina nebola uhradená cez Stripe v Tutlio (napr. bankovým prevodom alebo v hotovosti). Automatické vrátenie platby tu nie je k dispozícii.</p><p class=\"mt-2\">Ak chcete dohodnúť vrátenie platby, kontaktujte svojho doučovateľa <strong>{tutor}</strong> — použite e-mail alebo údaje z rezervácií či priamo od doučovateľa.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Zdá sa, že táto hodina nebola uhradená cez Stripe v Tutlio (napr. bankovým prevodom alebo v hotovosti). Automatické vrátenie platby tu nie je k dispozícii.</p><p class=\"mt-2\">Keďže študujete cez organizáciu, kontaktujte <strong>správcu organizácie</strong> (cez svojho doučovateľa alebo zverejnené kontakty organizácie).</p>",
  "stuSess.refundTutorFallback": "váš doučovateľ",
