  "orgTutorPolicy.title": "Interné pravidlá pre doučovateľov",
  "orgTutorPolicy.intro": "Pred používaním platformy si prečítajte interné pravidlá organizácie.",
  "orgTutorPolicy.acceptBtn": "Rozumiem",
  "orgTutorPolicy.viewBtn": "Zobraziť interné pravidlá",
  "orgTutorPolicy.s1Title": "1. Všeobecné ustanovenia",
  "orgTutorPolicy.s1Body": "Tieto pravidlá upravujú vaše používanie platformy Tutlio (ďalej len „platforma“) v úlohe učiteľa alebo doučovateľa (ďalej len „doučovateľ“). Na používanie platformy vás pozvala vzdelávacia agentúra, škola alebo doučovacie centrum, ktoré zastupujete (ďalej len „organizácia“). Technickú údržbu a podporu platformy zabezpečuje MB Tutlio. Používaním účtu súhlasíte s týmito pravidlami a zásadami ochrany osobných údajov.",
  "orgTutorPolicy.s2Title": "2. Správa účtu a rozvrhy",
  "orgTutorPolicy.s2Intro": "Platforma je navrhnutá tak, aby ste nemuseli tráviť čas dohadovaním termínov hodín so študentmi.",
  "orgTutorPolicy.s2Link": "Jedinečný odkaz: Máte pridelený osobný odkaz na rezerváciu hodín (podľa vyučovaných predmetov), prostredníctvom ktorého si študenti plánujú hodiny.",
  "orgTutorPolicy.s2Calendar": "Synchronizácia kalendára: Vaša dostupnosť priamo závisí od integrácie Google Calendar (2-smerná synchronizácia). Osobne zodpovedáte za správnosť a aktuálnosť voľných termínov zobrazených v kalendári. Platforma neumožní študentom rezervovať termíny, ktoré sú v kalendári označené ako obsadené.",
  "orgTutorPolicy.s2Security": "Bezpečnosť účtu: Váš účet je osobný. Prihlasovacie údaje musíte uchovávať v bezpečí a nesmiete ich zdieľať s tretími stranami.",
  "orgTutorPolicy.s3Title": "3. Rušenie hodín a čakacia listina",
  "orgTutorPolicy.s3Intro": "Platforma pomáha naplno využiť váš rozvrh a predchádzať neobsadeným termínom:",
  "orgTutorPolicy.s3Auto": "Ak študent zruší hodinu, platforma automaticky odošle upozornenie (SMS/e-mail) ostatným študentom na vašej čakacej listine a ponúkne im uvoľnený termín. Z vašej strany nie je potrebná ďalšia akcia.",
  "orgTutorPolicy.s3Rules": "Pravidlá rušenia hodín (predstih zrušenia a dôsledky) určuje vaša organizácia.",
  "orgTutorPolicy.s4Title": "4. Financie a platby",
  "orgTutorPolicy.s4Intro": "Nemusíte sa starať o fakturáciu ani výber platieb od rodičov:",
  "orgTutorPolicy.s4Advance": "Všetky platby študentov (alebo rodičov) za vaše hodiny sa vyberajú vopred cez platformu a prevádzajú sa priamo vašej organizácii.",
  "orgTutorPolicy.s4Confirmed": "Hodinu uskutočníte len vtedy, keď je v systéme potvrdená (teda už bola zaúčtovaná platba).",
  "orgTutorPolicy.s4Contact": "V otázkach odmeny, termínov výplat a ďalších finančných záležitostí sa obráťte priamo na správcu svojej organizácie. MB Tutlio nevykonáva žiadne priame finančné transakcie s doučovateľmi.",
  "orgTutorPolicy.s5Title": "5. Ochrana osobných údajov študentov (GDPR)",
  "orgTutorPolicy.s5Intro": "Ako doučovateľ máte prístup k osobným údajom študentov, interným poznámkam a študijným materiálom. Zaväzujete sa:",
  "orgTutorPolicy.s5Use": "Používať tieto údaje výlučne na organizáciu a realizáciu hodín.",
  "orgTutorPolicy.s5NoCopy": "Nekopírovať, neexportovať ani nešíriť kontaktné údaje študentov alebo rodičov mimo platformy.",
  "orgTutorPolicy.s5Notes": "Chrániť interné záznamy organizácie (poznámky o pokroku študentov), ktoré sú viditeľné len vám a správe organizácie, nie študentom ani rodičom.",
  "orgTutorPolicy.s5Termination": "Po ukončení pracovného vzťahu s organizáciou bude váš prístup k týmto údajom okamžite zrušený.",
  "orgTutorPolicy.s6Title": "6. Technická prevádzka a obmedzenie zodpovednosti",
  "orgTutorPolicy.s6Body": "Používanie platformy na nezákonné účely, šírenie škodlivých odkazov v učebných materiáloch alebo iné narúšanie systému je zakázané. MB Tutlio zabezpečuje prevádzku a technickú údržbu platformy, ale nezodpovedá za výpadky spôsobené vaším internetovým pripojením, poruchami zariadení alebo nesprávnym nastavením Google Calendar.",
  "orgTutorPolicy.s7Title": "7. Podpora a kontakty",
  "orgTutorPolicy.s7Org": "S otázkami o rozvrhu hodín, odmenách, priraďovaní študentov alebo organizácii práce sa obráťte na správcu svojej organizácie.",
  "orgTutorPolicy.s7Tech": "Pri technických chybách platformy (nefunkčná synchronizácia kalendára, nedoručené upozornenia) informujte správcu svojej organizácie, ktorý kontaktuje technickú podporu Tutlio.",
  "register.orgPolicyConsent": "Používaním našej platformy súhlasíte s",
  "register.orgPolicyLink": "internými pravidlami",
