  "quiz.info.story.solo.disclosure": "Ilustračné skúsenosti doučovateľov",
  "quiz.info.story.solo.name1": "Rasa",
  "quiz.info.story.solo.role1": "Doučovateľka matematiky",
  "quiz.info.story.solo.story1": "„Keď sú hodiny, údaje študentov a platby na jednom mieste, už netrávim piatkový večer skladaním celého týždňa zo správ.“",
