  "quiz.info.story.solo.role2": "Doučovateľ angličtiny",
  "quiz.info.story.solo.story2": "„Prehľadný kalendár a pripomienky mi umožňujú sústrediť sa na prípravu skvelých hodín namiesto opakovania rovnakej administratívy.“",
  "quiz.info.story.company.eyebrow": "Od zákazníka Tutlio",
