  "quiz.info.story.company.title": "Čo sa zmenilo pre tím PRO KLASĖ",
  "quiz.info.story.company.body": "Ich nastavenie spája plánovanie, vyhodnotenie hodín a vlastné pravidlá odmien do jedného každodenného postupu.",
  "quiz.info.story.company.disclosure": "Pracovný postup zákazníka",
