  "quiz.info.story.company.customerType": "Tím doučovacej organizácie",
  "quiz.offer.testimonial.company.role1": "Tím doučovacej organizácie",
  "quiz.info.story.company.story": "„Pred Tutlio boli zmeny hodín, komentáre a odpracované hodiny doučovateľov roztrúsené v správach. Teraz celý tím pracuje s rovnakým rozvrhom a na konci mesiaca nemusíme zháňať aktuálne údaje.“",
  "quiz.info.story.company.proof1": "Tímové plánovanie",
  "quiz.info.story.company.proof2": "Vlastné pravidlá odmien",
  "quiz.info.story.company.proof3": "Dohľad nad hodinami",
  "quiz.info.story.company.detail": "„Najväčšou zmenou bolo prispôsobenie schvaľovania, náhradných hodín a pravidiel odmien tomu, ako náš tím už funguje, namiesto toho, aby sme sa museli prispôsobiť všeobecnému procesu.“",
  "quiz.info.story.school.title": "Čo sa zmenilo pre VšĮ „Laisvi vaikai“",
  "quiz.info.story.school.body": "Ich tím prepája evidenciu študentov, zmluvy, splátky a účtovníctvo do jedného administratívneho postupu.",
  "quiz.info.story.school.brandAlt": "Logo VšĮ „Laisvi vaikai“",
