  "quiz.offer.testimonial.school.name1": "VšĮ „Laisvi vaikai“",
  "quiz.info.story.school.customerType": "Tím školskej administratívy",
  "quiz.offer.testimonial.school.role1": "Tím školskej administratívy",
  "quiz.info.story.school.story": "„Chceli sme jedno miesto, kde tím dokáže sledovať rodinu od zápisu a zmluvy až po každú splátku. Tutlio nám dáva túto nadväznosť bez vedenia paralelných tabuliek.“",
