  "quiz.info.story.school.proof3": "Exporty pre účtovníctvo",
  "quiz.info.story.school.detail": "„Najvýraznejším zlepšením je prehľad o stave zmluvy, podpisu a platby bez vypytovania sa viacerých ľudí alebo kontroly samostatných súborov.“",
  "quiz.offer.testimonial.school.copy1": "„Najvýraznejším zlepšením je prehľad o stave zmluvy, podpisu a platby bez vypytovania sa viacerých ľudí alebo kontroly samostatných súborov.“",
