  "quiz.offer.guarantee.title": "14-dňová záruka vrátenia peňazí",
  "quiz.offer.guarantee.body": "Ak vám Tutlio nevyhovuje, požiadajte o vrátenie peňazí počas prvých 14 dní. Bez otázok.",
  "quiz.offer.testimonials.eyebrow": "Tutlio v každodennej práci",
  "quiz.offer.testimonials.title.solo": "Čo si všímajú samostatní doučovatelia",
  "quiz.offer.testimonials.title.company": "Ako Tutlio podporuje doučovaciu organizáciu",
  "quiz.offer.testimonials.title.school": "Ako Tutlio prepája školskú administratívu",
  "quiz.offer.testimonials.pause": "Pozastaviť referencie",
  "quiz.offer.testimonials.play": "Prehrať referencie",
  "quiz.offer.testimonials.navigation": "Vybrať referenciu",
  "quiz.offer.testimonials.goTo": "Zobraziť referenciu {number}",
  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Doučovateľka chémie a biológie",
  "quiz.offer.testimonial.solo.copy3": "„Verejná stránka a rezervácia pod jedným odkazom pomáhajú novým študentom rýchlejšie sa rozhodnúť a ja už nemusím každému zvlášť posielať rovnaké informácie.“",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Doučovateľ fyziky",
  "quiz.offer.testimonial.solo.copy4": "„V kalendári okamžite vidím hodiny, zmeny a stavy platieb. Každodenná administratíva je oveľa kratšia a prehľadnejšia.“",
  "quiz.offer.testimonial.company.copy1": "„Zmeny hodín, komentáre doučovateľov a odpracované hodiny kedysi prichádzali v samostatných správach. Teraz administratívny tím vidí celý obraz v jednom rozvrhu.“",
  "quiz.offer.testimonial.company.name2": "Nezávislé doučovacie centrum",
  "quiz.offer.testimonial.company.role2": "Vlastník · 8 doučovateľov",
  "quiz.offer.testimonial.company.copy2": "„Pred prípravou výplat som piatkové večery trávil porovnávaním kalendára so správami doučovateľov. S Tutlio je väčšina tejto kontroly už hotová.“",
  "quiz.offer.testimonial.company.name3": "Jazykové štúdio",
  "quiz.offer.testimonial.company.role3": "Vedúci prevádzky · 14 doučovateľov",
  "quiz.offer.testimonial.company.copy3": "„Keď sa hodina presunie, tím hneď vidí rovnakú aktualizáciu. Máme menej následných správ a rodičia dostávajú oveľa jasnejšie odpovede.“",
  "quiz.offer.testimonial.company.name4": "Akadémia prípravy na skúšky",
  "quiz.offer.testimonial.company.role4": "Finančný koordinátor · 22 doučovateľov",
  "quiz.offer.testimonial.company.copy4": "„Naše pravidlá odmien doučovateľov sa líšia podľa typu hodiny, preto koniec mesiaca vyžadoval veľa manuálneho overovania. S postupom v Tutlio je tento proces oveľa pokojnejší.“",
  "quiz.offer.testimonial.school.name2": "Nezávislá komunitná škola",
  "quiz.offer.testimonial.school.role2": "Koordinátor prijímania · 86 študentov",
  "quiz.offer.testimonial.school.copy2": "„Obdobie zápisu kedysi znamenalo sledovanie formulárov, údajov rodičov a podpísaných zmlúv v oddelených priečinkoch. Teraz náš tím sleduje každú rodinu na jednom mieste.“",
  "quiz.offer.testimonial.school.name3": "Centrum mimoškolského vzdelávania",
  "quiz.offer.testimonial.school.role3": "Správca · 120 študentov",
  "quiz.offer.testimonial.school.copy3": "„Splátkové kalendáre výrazne upokojili sledovanie platieb. Pred kontaktovaním rodiča vidím, čo je splatné, namiesto ručného zostavovania zoznamu.“",
  "quiz.offer.testimonial.school.name4": "Umelecká škola",
  "quiz.offer.testimonial.school.role4": "Finančný koordinátor · 9 programov",
  "quiz.offer.testimonial.school.copy4": "„Účtovný export teraz vychádza z rovnakých záznamov, ktoré používame pre zmluvy a platby, takže koniec mesiaca prináša oveľa menej opráv.“",
  "quiz.offer.savings.eyebrow": "Odhadovaný vplyv na čas",
