  "landing.custom.badge": "Zásadný rozdiel",
  "landing.custom.title": "Softvér, ktorý sa prispôsobí vášmu spôsobu práce - nie naopak",
  "landing.custom.sub": "Každá škola aj agentúra funguje trochu inak. Keď štandardný postup nesedí, prispôsobíme Tutlio vášmu procesu - zvyčajne v týždňoch, nie v štvrťrokoch. Zopár vecí, ktoré sme už pre klientov postavili:",
  "landing.custom.ex1Title": "Ročné zmluvy s elektronickým podpisom",
  "landing.custom.ex1Desc": "Súkromná škola potrebovala, aby rodičia podpisovali ročné zmluvy elektronicky, platili v splátkach a aby sa každá platba objavila v exporte pripravenom pre účtovníctvo. Celý cyklus dnes beží vnútri Tutlia.",
  "landing.custom.ex2Title": "Pravidlá odmien a provízií doučovateľov",
  "landing.custom.ex2Desc": "Agentúra platí každého doučovateľa podľa predmetu a typu hodiny a k tomu si pripočítava firemnú províziu. Ich pravidlá sme namodelovali, takže mesačné výkazy doučovateľov aj faktúry vznikajú automaticky.",
  "landing.custom.ex3Title": "Ponuky pre rodičov na jedno kliknutie",
  "landing.custom.ex3Desc": "Škola chcela ponúkať doplnkové hodiny e-mailom a nechať rodičov prijať ich jediným kliknutím - bez účtu a bez tlače. Prijatie, vyúčtovanie aj pozvánka na prvú hodinu dnes prebiehajú samy.",
  "landing.custom.ex4Title": "Vaša značka na vašom webe",
  "landing.custom.ex4Desc": "Organizácia chcela vlastné logo a farby a k tomu prihlásenie vložené priamo do svojho webu, aby študenti ani rodičia nemali pocit, že ho opustili. Tutlio dnes beží pod ich značkou.",
  "landing.custom.note": "Nič z toho nie je zvláštna edícia. Každá úprava sa stane súčasťou toho istého produktu, ktorý váš tím už používa, vrátane všetkých budúcich aktualizácií.",
  "landing.custom.cta": "Povedzte nám, ako pracujete",
  "landing.custom.soloTitle": "Niečo vám chýba?",
  "landing.custom.soloNote": "Pravidelne vyvíjame funkcie pre jednotlivých klientov - od jedného platobného pravidla po celý pracovný postup. Napíšte nám, čo by vám ušetrilo čas.",
  "stats.cancellationPartTutor": "doučovateľ: {count}",
