  "compare.teachworks.faq.a2": "Natívne nie. Tutlio exportuje účtovné údaje do súborov XLSX, synchronizuje lekcie s Kalendárom Google a pri každej lekcii uchováva odkaz na online stretnutie, takže môžete použiť Zoom, Google Meet alebo iný nástroj. Verejné API ani konektor pre Zapier dnes neexistujú. Teachworks inzeruje QuickBooks, Zapier, Zoom a prístup k API v balíkoch Growth a Premium.",
