  "compare.teachworks.verdict": "Teachworks je pružná voľba bohatá na integrácie pre anglicky hovoriace centrá so stredným počtom lekcií. Tutlio sa hodí lepšie, keď chcete predvídateľnú cenu za lektora, zmluvy a postupy pre rodičov, rozhranie v európskych jazykoch a partnera, ktorý softvér prispôsobí vám.",
  "compare.oases.metaDesc": "Tutlio vs Oases Online pre doučovacie centrá a programy s viacerými pobočkami: cena podľa počtu aktívnych študentov namiesto licencií na lektora, párovanie, testovanie, zmluvy, jazyky a funkcie na mieru.",
  "compare.oases.intro1": "Oases Online je severoamerická platforma na správu doučovacích centier, firiem pripravujúcich na skúšky, popoludňajších programov a prevádzok s viacerými pobočkami či franšízami vrátane dodávateľov pracujúcich na verejné zákazky. Pokrýva rozvrh, párovanie lektora so študentom, fakturáciu z kalendára, odmeny lektorov, testovanie a správy o pokroku, portál pre rodičov, marketingové nástroje a manažérske výkazy.",
  "compare.oases.intro2": "Tutlio slúži doučovacím školám a agentúram s ľahším a rýchlejším rozbehom: kalendár a vlastná rezervácia, platby cez Stripe a faktúry, zmluvy so splátkami, odmeny lektorov, rodičovské účty, čakacia listina, tabuľa a 36 jazykov rozhrania - s cenou za lektora namiesto za aktívneho študenta, so skúšobným obdobím a funkciami na mieru na požiadanie.",
  "compare.oases.glance.bestFor": "Severoamerické centrá a programy s viacerými pobočkami, ktoré potrebujú párovanie lektorov, testovanie a výkazy pre veľké počty študentov",
  "compare.oases.glance.pricingModel": "Mesačné pásma podľa počtu aktívnych študentov, s podnikovou cenou nad 350 študentov",
