  "compare.oases.tutlioFor1": "Chcete začať v malom a platiť za lektora, nie za aktívneho študenta - Tutlio má neobmedzený počet študentov a skúšobné obdobie.",
  "compare.oases.tutlioFor2": "Vaši rodičia podpisujú zmluvy a platia v splátkach alebo prijímajú ponuky lekcií navyše e-mailom - Tutlio túto cestu vedie vrátane elektronického podpisu v Litve.",
  "compare.oases.tutlioFor3": "Pôsobíte v Európe a potrebujete rozhranie, faktúry a e-maily v miestnych jazykoch, ceny v EUR alebo PLN a produkt, ktorý sa prispôsobí vášmu postupu.",
  "compare.oases.themFor1": "Párujete stovky študentov s lektormi podľa zručností, lokality a dostupnosti a potrebujete na to vstavaný párovací systém.",
  "compare.oases.themFor2": "Testovanie, online skúšky a plány učenia sú súčasťou vašej služby a pokrok hlásite školským obvodom alebo obstarávateľom.",
  "compare.oases.themFor3": "Ste severoamerická prevádzka s viacerými pobočkami alebo franšízami a chcete kampane v Mailchimpe, SMS cez Twilio a manažérske výkazy na jednej platforme.",
  "compare.oases.faq.q1": "Páruje Tutlio študentov s lektormi automaticky ako Oases?",
