  "compare.oases.verdict": "Oases Online je postavený pre veľké severoamerické prevádzky, ktoré potrebujú párovanie, testovanie a zmluvné výkazy vo veľkom. Tutlio sa lepšie hodí doučovacím školám a agentúram - najmä v Európe - ktoré chcú cenu za lektora, zmluvy a postupy pre rodičov, miestne jazyky a tím, ktorý produkt prispôsobí im.",
